import{z as i,x as s,o as e,c as C,q as n,j as o,D as B,d as A,s as l,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"超级明星与赢者通拿","description":"","frontmatter":{"title":"超级明星与赢者通拿","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/superstar-labor.md","filePath":"econ/superstar-labor.md","lastUpdated":1791063341000}'),d={name:"econ/superstar-labor.md"};function p(D,E,F,m,h,u){const r=s("Mermaid");return e(),C("div",null,[E[2]||(E[2]=n('<h1 id="超级明星与赢者通拿" tabindex="-1">超级明星与赢者通拿 <a class="header-anchor" href="#超级明星与赢者通拿" aria-label="Permalink to &quot;超级明星与赢者通拿&quot;">​</a></h1><div class="epigraph"><p>技术把每个观众送到同一位歌手面前；才能上小小的差距，被市场放大成天文数字的收入差。</p><footer>—— 据 Rosen, The Economics of Superstars, AER, 1981；Gabaix and Landier, Why Has CEO Pay Increased So Much?, QJE, 2008 整理</footer></div><p><a href="/econ/signaling-spence-labor">上一课</a>把教育溢价拆成技能与标签两笔账，工资结构的主叙事至此齐了：供需定溢价、人力资本定剖面、属性定补偿、信号分标签。本课收「谁赚得多」的最后一块——右尾：为什么顶尖者与第二名的收入差远大于才能差。Rosen 1981 的超级明星机制把答案压在市场规模与复制技术上。到此为止，这门课都在价格出清的前提下谈定价；下一单元换问题——没成交的人去哪了：失业的存量-流量。「谁赚得多」收在这里，给下一单元留下缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的框架是两组劳动的相对价格；右尾问的是分布形状。同一职业内，第一名与第一百名的收入可以差百倍、千倍，而才能差远没有这么大——两组相对价格的模型装不下这个凸性。反例也摆在明处：护士、水管工、中小学教师的收入右尾很平。缺口是：什么条件让微小的才能差兑换成巨大的收入差，什么条件不让。</p><h3 id="两个假设" tabindex="-1">两个假设 <a class="header-anchor" href="#两个假设" aria-label="Permalink to &quot;两个假设&quot;">​</a></h3><p>Rosen 的机制只要两条。一、才能不完全替代：第二好的歌手替代不了最好的，观众认人。二、联合消费：同一场演出、同一张唱片可以同时卖给近乎无限多的人，多一个观众的成本近零。两条一起，需求涌向才能分布的右端，收入对才能是凸函数。</p><p><span class="marginnote">直觉类比：技术让全世界的听众挤进同一间音乐厅——座位从一万个变成十亿个，台上还是那一位第一名。第二名唱得只差一点点，却几乎没人听：才能差一毫米，舞台差一光年。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Rosen 的基准：才能 \\(s\\) 连续分布，市场大小为 \\(N\\)。均衡里才能的排序决定市场份额，收入取对数后对才能近似线性、并随市场技术整体放大：</p> \\[\\ln y = \\alpha + \\beta\\, s + \\gamma \\ln N, \\qquad \\beta, \\gamma \\gt 0 . \\]<p>唱片与广播之前，最好的歌手只能服务本地市场，\\(N\\) 被剧场座位钉死；复制技术把 \\(N\\) 放大几个数量级，右尾收入被同一比例重写——「技术放大」是模型里的 \\(\\gamma\\ln N\\) 项，不是修辞。同一机制走到高管：公司规模巨大且分散，CEO 的边际判断被规模乘大。Gabaix–Landier 2008 用美国大公司市值校准：市值约六倍的增长对应 CEO 薪酬约六倍的增长，比例吻合把「治理全面失效」的解释挤出大半；激励与代理的内脏在<a href="/econ/executive-compensation">高管薪酬与激励</a>里，这里只谈规模项。职业体育与娱乐的数据形态与模型同构：竞技差距极小（百米前八名在百分之一秒内），收入差千倍级；转会费、代言、转播分成随名次陡降。</p>',12)),(e(),o(t,null,{default:B(()=>[l(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20OCC%5B%22%E4%B8%80%E7%A7%8D%E8%81%8C%E4%B8%9A%22%5D%20--%3E%20H1%7B%22%E4%BA%A7%E5%87%BA%E8%83%BD%E5%90%8C%E6%97%B6%E5%8D%96%E7%BB%99%E5%BE%88%E5%A4%9A%E4%BA%BA%E5%90%97%EF%BC%9F%22%7D%0A%20%20H1%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E4%B8%80%E5%B0%8F%E6%97%B6%E5%8F%AA%E6%9C%8D%E5%8A%A1%E4%B8%80%E4%BA%BA%22%7C%20FLAT%5B%22%E5%8F%B3%E5%B0%BE%E5%B9%B3%EF%BC%9A%E6%8A%A4%E5%A3%AB%E3%80%81%E6%B0%B4%E7%AE%A1%E5%B7%A5%E3%80%81%E6%95%99%E5%B8%88%22%5D%0A%20%20H1%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E5%94%B1%E7%89%87%E3%80%81%E8%BD%AF%E4%BB%B6%E3%80%81%E7%9B%B4%E6%92%AD%22%7C%20H2%7B%22%E8%A7%82%E4%BC%97%E5%88%86%E5%BE%97%E5%87%BA%E8%B0%81%E6%9C%80%E5%A5%BD%E5%90%97%EF%BC%9F%22%7D%0A%20%20H2%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E8%B4%A8%E9%87%8F%E9%9A%BE%E8%A7%82%E5%AF%9F%E3%80%81%E9%9A%BE%E6%8E%92%E5%90%8D%22%7C%20FLAT2%5B%22%E5%B8%82%E5%9C%BA%E5%88%86%E6%95%A3%EF%BC%8C%E8%B5%A2%E8%80%85%E9%80%9A%E6%8B%BF%E4%B8%8D%E6%88%90%E7%AB%8B%22%5D%0A%20%20H2%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E6%A6%9C%E5%8D%95%E3%80%81%E5%8F%A3%E7%A2%91%E3%80%81%E6%B5%81%E9%87%8F%22%7C%20SUPER%5B%22%E8%B6%85%E7%BA%A7%E6%98%8E%E6%98%9F%EF%BC%9A%E6%94%B6%E5%85%A5%E5%AF%B9%E6%89%8D%E8%83%BD%E6%98%AF%E5%87%B8%E5%87%BD%E6%95%B0%22%5D%0A%20%20SUPER%20--%3E%20NUP%5B%22%E5%A4%8D%E5%88%B6%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%B8%82%E5%9C%BA%E8%A7%84%E6%A8%A1%E5%86%8D%E6%94%BE%E5%A4%A7%E5%B7%AE%E8%B7%9D%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"数字实例：取 \\(\\beta=0.3\\)。两位歌手的才能分只差 1，收入比就是 \\(e^{0.3}\\approx 1.35\\)；才能分差 10，收入比是 \\(e^{3}\\approx 20\\) 倍——才能的线性差距，经过凸性兑换成收入的数量级差距。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"放大通道是一张清单：复制成本近零（唱片、流媒体、软件）；市场半径（全球化把 \\(N\\) 从城市放大到全球）；排名与中介技术（榜单把注意力更集中，发现与集中互相加强）。反例划出边界：护士与水管工的产出不联合消费（一小时只服务一人）、质量难观察也难排名，两条假设都不满足，右尾不会因为技术进步而变平。右尾因此既不是市场失灵也不是道德问题，是生产与复制技术的函数；技术一变，分布形状跟着变。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"Gabaix–Landier 2008 的核心事实：美国大公司市值在 1980–2004 年间约增六倍，按其比例模型推得的 CEO 薪酬增长与之同量级。争议在「规模项算不算出清」，不在数据本身；把它直接读成治理失败的证据，会漏掉规模这一项。")],-1)),(e(),o(t,null,{default:B(()=>[l(r,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E6%89%8D%E8%83%BD%E4%B8%8D%E5%AE%8C%E5%85%A8%E6%9B%BF%E4%BB%A3%EF%BC%9A%E8%A7%82%E4%BC%97%E8%AE%A4%E4%BA%BA%22%5D%20--%3E%20CONC%5B%22%E9%9C%80%E6%B1%82%E9%9B%86%E4%B8%AD%E5%88%B0%E6%89%8D%E8%83%BD%E5%88%86%E5%B8%83%E5%8F%B3%E7%AB%AF%22%5D%0A%20%20T2%5B%22%E8%81%94%E5%90%88%E6%B6%88%E8%B4%B9%EF%BC%9A%E5%A4%9A%E4%B8%80%E8%A7%82%E4%BC%97%E6%88%90%E6%9C%AC%E8%BF%91%E9%9B%B6%22%5D%20--%3E%20SCALE%5B%22%E5%B8%82%E5%9C%BA%E8%A7%84%E6%A8%A1%20N%20%E4%B8%8E%E5%A4%8D%E5%88%B6%E6%8A%80%E6%9C%AF%22%5D%0A%20%20TECH%5B%22%E5%B9%BF%E6%92%AD%E3%80%81%E5%94%B1%E7%89%87%E3%80%81%E6%B5%81%E5%AA%92%E4%BD%93%22%5D%20--%3E%20SCALE%0A%20%20SCALE%20--%3E%20CONV%5B%22%E6%94%B6%E5%85%A5%E5%AF%B9%E6%89%8D%E8%83%BD%E5%87%B8%EF%BC%9A%E8%B5%A2%E8%80%85%E9%80%9A%E6%8B%BF%22%5D%0A%20%20CONC%20--%3E%20CONV%0A%20%20CONV%20--%3E%20TAIL%5B%22%E8%81%8C%E4%B8%9A%E5%86%85%E6%94%B6%E5%85%A5%E5%8F%B3%E5%B0%BE%EF%BC%9A%E6%98%8E%E6%98%9F%E3%80%81CEO%E3%80%81%E4%BD%93%E8%82%B2%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课解释既定才能分布下收入的凸性，不解释才能分布怎么形成：童年投资、选拔体系、以及为挤进右尾的过度竞赛投入——竞赛性耗散的口径在<a href="/econ/all-pay-auction">全支付拍卖</a>里。也别把赢者通拿当成所有行业的宿命：复制成本高、排名难、服务半径有限的职业，右尾不会变。政策上，再分配的争论要先承认机制：税收与规制改变不了联合消费技术，改的是事后分配——把两件事混在一句话里，是右尾讨论最常见的错位。</p><p><span class="marginnote">为什么重要：判断一个行业会不会走向赢者通拿，先看两个可观察指标——复制成本与可排名性。直播让化妆师、游戏玩家明星化（复制近零、可排名），却没能造出「水管工明星」：技术改的是复制，不是服务半径。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>超级明星只要两个假设：才能不完全替代、联合消费近零成本。</li><li>市场规模与复制技术放大收入的凸性；右尾是技术的函数。</li><li>CEO 薪酬约六倍增长与大公司市值约六倍增长同比例（Gabaix–Landier 2008），规模项是主解释候选。</li><li>护士与水管工没有超级明星：联合消费与可排名性不成立。</li><li>工资结构收束于此；下一单元转出清失败——失业的存量-流量与贝弗里奇。</li><li>出处：Rosen, AER 1981；Frank and Cook, The Winner-Take-All Society, 1995；Gabaix and Landier, QJE 2008。</li></ul>',5))])}const f=i(d,[["render",p]]);export{b as __pageData,f as default};
